package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;
import java.util.List;
import java.util.Set;

/** A version of a sheet's policy: made by a change to one of its policy settings (see {@link #KEYS}),
 *  numbered from 1 per sheet in the order made, in force from its from-date (null: none, always). */
@Entity
@Table(name = "policy_version")
public class PolicyVersion {

    /** The settings that are versioned together as the sheet's policy. */
    public static final Set<String> KEYS = Set.of(Rounding.KEY, "floor", "cap", "terms", "late-pct", "clerk-limit");

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "number", nullable = false)
    private int number;

    @Column(name = "setting_key", nullable = false)
    private String key;

    @Column(name = "from_date")
    private LocalDate from;

    /** The sheet's today when the version was made. */
    @Column(name = "recorded_on", nullable = false)
    private LocalDate recordedOn;

    protected PolicyVersion() {
    }

    public PolicyVersion(String sheetId, int number, String key, LocalDate from, LocalDate recordedOn) {
        this.sheetId = sheetId;
        this.number = number;
        this.key = key;
        this.from = from;
        this.recordedOn = recordedOn;
    }

    public int getNumber() {
        return number;
    }

    public String getKey() {
        return key;
    }

    public LocalDate getFrom() {
        return from;
    }

    public LocalDate getRecordedOn() {
        return recordedOn;
    }

    /** Whether the version is in force on a day: it has no from-date, or its from-date is on or before it. */
    public boolean countsOn(LocalDate day) {
        return from == null || !from.isAfter(day);
    }

    /** The version of the policy in force on a day: the number of the versions given in force on it. */
    public static int on(List<PolicyVersion> versions, LocalDate day) {
        return (int) versions.stream().filter(v -> v.countsOn(day)).count();
    }
}
                    reviewThreshold == null ? null : reviewThreshold.setScale(2).toPlainString(), escalateAfter,
                    reviewSla, String.join(",", proofKinds), defaultGrade, twoDecimals(gradeClerkLimits),
                    scoreMid, scoreHigh, scoreLog, maxOpen, pendingSla, policyVersions.size(),
                    policyVersions.stream().map(PolicyVersionView::of).toList());
        }
    }

    /** A policy version: its number, the setting whose change made it, and its from-date (null: none,
     *  in force always). */
    public record PolicyVersionView(int number, String key, LocalDate from) {
        static PolicyVersionView of(PolicyVersion v) {
            return new PolicyVersionView(v.getNumber(), v.getKey(), v.getFrom());
        }
    }

    /** Values by grade as text with two decimals. */
    private static Map<String, String> twoDecimals(Map<String, BigDecimal> values) {
        Map<String, String> view = new TreeMap<>();
        values.forEach((grade, v) -> view.put(grade, v.setScale(2).toPlainString()));
        return view;
    }

    /** A whole number of days a dated setting takes from a date; null when blank. */
    public record DatedDays(LocalDate from, Integer value) {
        static DatedDays of(SettingValue v) {
            return new DatedDays(v.getFrom(), v.getValue() == null ? null : v.getValue().intValue());
        }
    }

    /** A value a dated setting takes from a date, as text with two decimals; null when blank. */
    public record DatedValue(LocalDate from, String value) {
    public List<SettingValue> recorded(String id, String key) {
        return settingValues.findBySheetIdAndKeyOrderByFrom(id, key);
    }

    /** Record a dated setting's value from a date (the sheet's today when none is given), keeping the
     *  values already recorded (one from the same date is replaced); recorded in the audit even when
     *  it is unchanged, with the from-date at the end when one was given. A policy setting (see
     *  {@link PolicyVersion#KEYS}) makes a new policy version from that date. */
    private Sheet record(String id, String user, String key, BigDecimal value, String shown, LocalDate from) {
        Sheet sheet = load(id, user);
        LocalDate on = from != null ? from : sheet.getToday();
        SettingValue v = settingValues.findById(new SettingValue.Key(id, key, on))
                .orElseGet(() -> new SettingValue(id, key, on, value));
        v.setValue(value);
        settingValues.saveAndFlush(v);
        if (PolicyVersion.KEYS.contains(key)) {
            policyVersions.saveAndFlush(
                    new PolicyVersion(id, policyVersions.countBySheetId(id) + 1, key, on, sheet.getToday()));
        }
        history.record(id);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + id + " by=" + user + " key=" + key + " value=" + shown
                + (from != null ? " from=" + from : ""));
        return sheet;
    }

    /** The number of the sheet's current policy version: how many have been made; 0 when none has. */
    @Transactional(readOnly = true)
    public int policyVersion(String id) {
        return policyVersions.countBySheetId(id);
    }

    /** The sheet's policy versions, the first made first. */
    @Transactional(readOnly = true)
    public List<PolicyVersion> policyVersions(String id) {
        return policyVersions.findBySheetIdOrderByNumber(id);
    }

